import {getPostTemplate,POST_TEMPLATES} from './post-scratch-catalogue.js?v=layout-flow-2';
export const ARTWORK_CHOICES=POST_TEMPLATES.filter(t=>t.id!=='custom-image').map(t=>({id:t.id,name:t.name}));
export const MAX_ARTWORK_DATA=2400000;
export const artworkSources=['original','upload',...ARTWORK_CHOICES.map(t=>t.id)];
// Only raster data URLs generated by the editor or restored from backups.
// No remote URLs, executable SVG or arbitrary HTML can be published.
function rasterData(value){
 if(typeof value!=='string'||value.length>MAX_ARTWORK_DATA)fail();
 const m=/^data:image\/(png|jpeg|webp);base64,([A-Za-z0-9+/]+={0,2})$/.exec(value);
 if(!m||m[2].length%4!==0||m[2].length<32)fail();
 let bytes;try{bytes=atob(m[2].slice(0,32));}catch{fail();}
 const matches=m[1]==='png'?bytes.startsWith('\x89PNG\r\n\x1a\n')&&bytes.slice(12,16)==='IHDR':m[1]==='jpeg'?bytes.charCodeAt(0)===255&&bytes.charCodeAt(1)===216&&bytes.charCodeAt(2)===255:bytes.slice(0,4)==='RIFF'&&bytes.slice(8,12)==='WEBP';
 if(!matches)fail();
 return value;
}
export const FONTS=[
 'Georgia, "Times New Roman", serif','Arial, Helvetica, sans-serif','"Arial Black", Arial, Helvetica, sans-serif',
 '"Apple Chancery", "Segoe Script", Georgia, serif','Georgia, serif','Arial, sans-serif',
 'Verdana, sans-serif','"Trebuchet MS", sans-serif','"Courier New", monospace','"Times New Roman", serif','Impact, sans-serif'
];
export const clone=x=>JSON.parse(JSON.stringify(x));
export const isStudioTemplateId=id=>typeof id==='string'&&/^studio-[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/.test(id);
export function defaultDesign(id,entry){
 const custom=isStudioTemplateId(id),baseId=custom?entry?.baseId:id;
 const base=getPostTemplate(baseId);if(!base||custom&&(!entry||entry.id!==id||baseId==='custom-image'))return null;
 const t=clone(base);
 t.decor=t.decor||[];t.panels=t.panels||[];t.showBackground=true;t.backgroundFill='#ffffff';t.artworkSource='original';t.artworkData='';t.artworkFit='contain';
 t.illustration=['pop-panels','doodle-party'].includes(baseId)?{x:baseId==='pop-panels'?40:110,y:baseId==='pop-panels'?220:320,w:baseId==='pop-panels'?236:340,h:baseId==='pop-panels'?260:300}:null;
 if(custom){Object.assign(t,{id,baseId,name:entry.name,collection:'Studio templates',description:'Custom Template Studio design.'});if(entry.blank){t.showBackground=false;t.backgroundFill='#ffffff';t.decor=[];t.illustration=null;t.zones=t.zones.map(z=>{const {glow,outline,...rest}=z;return {...rest,ink:'#222222'};});t.panels=t.panels.map(p=>({...p,fill:'#f3f4f6',stroke:'#d1d5db',ink:'#222222',...(p.key==='image'?{}:{labelInk:'#222222',accent:'#374151',iconBg:'none',divider:'#d1d5db'})}));if(!t.photo.full)t.photo.frame='#f3f4f6';}}
 return t;
}
const fail=()=>{throw Error('Invalid template design. Check geometry and style values.');};
const num=(x,min,max)=>{if(typeof x!=='number'||!Number.isFinite(x)||x<min||x>max)fail();return x;};
const str=(x,max)=>{if(typeof x!=='string'||x.length>max)fail();return x;};
const bool=x=>{if(typeof x!=='boolean')fail();return x;};
const color=x=>{if(typeof x!=='string'||!/^#[0-9a-f]{3}(?:[0-9a-f]{3})?$/i.test(x)&&x!=='none')fail();return x;};
const font=x=>{if(!FONTS.includes(x))fail();return x;};
const choice=(x,a)=>{if(!a.includes(x))fail();return x;};
const obj=x=>{if(!x||typeof x!=='object'||Array.isArray(x))fail();return x;};
const list=(x,max)=>{if(!Array.isArray(x)||x.length>max)fail();return x;};
function box(o){obj(o);const x=num(o.x,0,900),y=num(o.y,0,1200),w=num(o.w,12,900),h=num(o.h,12,1200);if(x+w>900.01||y+h>1200.01)fail();return {x,y,w,h};}
const opt=(o,key,fn,d)=>o[key]===undefined?d:fn(o[key]);
function style(z){return {size:num(z.size,12,200),family:font(z.family),weight:num(z.weight,100,900),ink:color(z.ink),align:choice(z.align,['left','center','right']),italic:opt(z,'italic',bool,false),upper:opt(z,'upper',bool,false),noWordSplit:opt(z,'noWordSplit',bool,true),spacing:opt(z,'spacing',x=>num(x,0,20),0),hidden:opt(z,'hidden',bool,false),useTemplateInk:opt(z,'useTemplateInk',bool,false),...(z.glow?{glow:color(z.glow)}:{}),...(z.outline?{outline:color(z.outline)}:{})};}
// Normalize persisted legacy headings on read and write without changing their geometry or personal values.
const personLabel=key=>key==='recipient'?'For You':['sender','senderLine'].includes(key)?'From Me':null;
const samplePersonName=/\b(?:Michael|Chloe)\b/iu;
function removeSamplePersonNames(value){
 return value.replace(/\b(?:Michael|Chloe)\b/giu,'').replace(/\s{2,}/g,' ').replace(/^[\s:;,/–—-]+|[\s:;,/–—-]+$/g,'').trim();
}
function personWording(key,value){const name=personLabel(key);if(!name||typeof value!=='string')return value;
 const legacy=key==='recipient'?/^(recipient|for you|to)$/i:/^(sender|from|host|from\s*(?:\/|or)\s*(?:host|sender)|from me)$/i;
 if(samplePersonName.test(value)){const cleaned=removeSamplePersonNames(value);return !cleaned||legacy.test(cleaned)?name:cleaned;}
 return legacy.test(value.trim())?name:value;
}
function zoneWording(z){
 const mode=z.textMode===undefined?undefined:choice(z.textMode,['customer','fixed']);
 let wording=z.templateText===undefined?undefined:str(z.templateText,1000);
 if(personLabel(z.key)&&wording!==undefined&&samplePersonName.test(wording)){
  const cleaned=removeSamplePersonNames(wording);
  // Old demo names must never become permanent customer names.
  if(!cleaned||/^(for|to|from|recipient|sender|host|for you|from me|from\s*\/\s*host)$/i.test(cleaned))return {textMode:'customer'};
  wording=personWording(z.key,cleaned);
 }
 return {...(wording!==undefined?{templateText:personWording(z.key,wording)}:{}),...(mode!==undefined?{textMode:mode}:{})};
}
function panel(p,keys){obj(p);if(!keys.has(p.key))fail();const b=box(p);const out={key:p.key,...b,fill:color(p.fill),stroke:color(p.stroke),sw:num(p.sw,0,30),rx:num(p.rx,0,200),ink:color(p.ink)};
 if(p.key==='image')return out;
 return {...out,label:personWording(p.key,str(p.label,80)),icon:choice(p.icon,['','date','time','venue','venueAddress','sender','recipient']),accent:color(p.accent),gutter:num(p.gutter,0,b.w-1),labelH:num(p.labelH,0,b.h-1),align:choice(p.align,['left','center','right']),family:font(p.family),iconBg:p.iconBg?color(p.iconBg):'',labelInk:color(p.labelInk),variant:choice(p.variant,['standard','paper-entry','comic-metric','comic-value']),valueBox:p.valueBox?box(p.valueBox):null,divider:color(p.divider)};
}
function decoration(d){obj(d);const kind=choice(d.kind,['rect','ellipse','line','path','text']);
 if(kind==='text')return {kind,...box(d),...style(d),text:str(d.text,300)};
 const stroke=color(d.stroke),sw=num(d.sw,0,30);
 if(kind==='line')return {kind,x1:num(d.x1,0,900),y1:num(d.y1,0,1200),x2:num(d.x2,0,900),y2:num(d.y2,0,1200),stroke,sw,...(d.dash?{dash:str(d.dash,40).match(/^[0-9. ,]+$/)?d.dash:fail()}: {})};
 const fill=color(d.fill);
 if(kind==='path'){const path=str(d.d,4000);if(!/^[MmLlHhVvCcSsQqTtAaZz0-9eE+.,\s-]+$/.test(path))fail();return {kind,d:path,fill,stroke,sw,tx:opt(d,'tx',x=>num(x,-900,900),0),ty:opt(d,'ty',x=>num(x,-1200,1200),0)};}
 return {kind,...box(d),fill,stroke,sw,...(kind==='rect'?{rx:num(d.rx,0,200)}:{})};
}
export function validateDesign(id,input,entry){
 const base=defaultDesign(id,entry);if(!base)fail();obj(input);if(input.id!==id)fail();
 const keys=new Set(base.zones.map(z=>z.key)),seen=new Set();
 const zones=list(input.zones,10).map(z=>{obj(z);if(!keys.has(z.key)||seen.has(z.key))fail();seen.add(z.key);if(z.textMode==='fixed'&&(typeof z.templateText!=='string'||!z.templateText.trim()))fail();return {key:z.key,...box(z),...style(z),...zoneWording(z)};});
 if(seen.size!==keys.size)fail();
 const allowed=new Set(base.panels.map(p=>p.key)),ps=new Set();
 const panels=list(input.panels,15).map(p=>{if(ps.has(p.key))fail();ps.add(p.key);return panel(p,allowed);});
 const p=obj(input.photo);const photo={...box(p),...(base.photo.full?{full:true}:{radius:num(p.radius,0,200),frame:color(p.frame),primary:true})};
 const illustration=input.illustration===null?null:base.illustration?box(input.illustration):fail();
 const artworkSource=opt(input,'artworkSource',x=>choice(x,artworkSources),'original');
 const artworkData=artworkSource==='upload'?rasterData(input.artworkData):'';
 const artworkFit=opt(input,'artworkFit',x=>choice(x,['contain','cover']),'contain');
 return {...base,zones,panels,photo,decor:list(input.decor,100).map(decoration),illustration,showBackground:bool(input.showBackground),backgroundFill:color(input.backgroundFill),artworkSource,artworkData,artworkFit};
}

 // Required layout elements cannot be removed, concealed or placed on top of one another.
 // Custom Image is intentionally a full-card background, not a competing foreground image.
 export function assertTemplateLayout(t){
  const keys=['eventName','subtitle','recipient','date','time','venue','venueAddress','message','link'];
  if(t.zones.length!==10||!keys.every(k=>t.zones.some(z=>z.key===k&&!z.hidden))||!t.zones.some(z=>['sender','senderLine'].includes(z.key)&&!z.hidden))throw Error('All ten editable fields must remain visible in the template layout.');
  const boxes=[...t.zones,...(t.photo.full?[]:[{...t.photo,key:'image'}])];
  for(const [i,a] of boxes.entries()){
   if(a.x<0||a.y<0||a.x+a.w>900.01||a.y+a.h>1200.01)throw Error('Field outside the card: '+a.key);
   for(const b of boxes.slice(i+1))if(a.x<b.x+b.w-.01&&a.x+a.w>b.x+.01&&a.y<b.y+b.h-.01&&a.y+a.h>b.y+.01)throw Error('Layout overlap: '+a.key+' / '+b.key+'. Move or resize these elements before publishing.');
  }
  return t;
 }
